145	    fn yaml_files(dir: &Path) -> Vec<PathBuf> {
146	        if !dir.is_dir() {
147	            return Vec::new();
148	        }
149	        let mut files: Vec<PathBuf> = fs::read_dir(dir)
150	            .into_iter()
151	            .flatten()
152	            .filter_map(|entry| entry.ok())
153	            .map(|entry| entry.path())
154	            .filter(|path| {
155	                path.extension()
156	                    .is_some_and(|ext| ext == "yml" || ext == "yaml")
157	            })
158	            .collect();
159	        files.sort();
160	        files
161	    }
162	
163	    fn file_stems(paths: &[PathBuf]) -> Vec<String> {
164	        paths
165	            .iter()
166	            .filter_map(|p| {
167	                p.file_stem()
168	                    .and_then(|s| s.to_str())
169	                    .map(|s| s.to_string())
170	            })
171	            .collect()
172	    }
173	}
