            skip_behavior: "run_anyway".to_string(),
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        assert_eq!(
            cmd.build_options(&crate::config::BivvyConfig::default())
                .skip_behavior,
            SkipBehavior::RunAnyway
        );
    }

