                command: "".to_string(),
            },
        );

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "empty-var-command"));
    }

    #[test]
    fn validates_computed_var_whitespace_only_command() {
        let mut config = BivvyConfig::default();
