    #[test]
    fn lint_targeted_workflow_does_not_parse_other_workflow_files() {
        // A malformed sibling workflow file must NOT block targeted lint of
        // a different workflow.
        let temp = setup_project("app_name: Test\n");
        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        fs::write(
            workflows_dir.join("good.yml"),
            r#"
steps:
  hello:
    command: echo hello
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();
        fs::write(
            workflows_dir.join("broken.yml"),
            "this: is: not: valid: yaml: at all",
        )
        .unwrap();

        let args = LintArgs {
            target: Some("good".to_string()),
            ..Default::default()
        };
        let cmd = LintCommand::new(temp.path(), args);
        let mut ui = MockUI::new();
        let result = cmd.execute(&mut ui).unwrap();
        assert!(result.success);
    }

    #[test]
    fn lint_unknown_target_errors_with_available_list() {
        let temp = setup_project("app_name: Test\n");
        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        fs::write(workflows_dir.join("ci.yml"), "steps: []").unwrap();

        let args = LintArgs {
            target: Some("nonexistent".to_string()),
            ..Default::default()
        };
        let cmd = LintCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();
        assert!(!result.success);
        assert!(ui
            .messages()
            .iter()
            .chain(ui.errors().iter())
            .any(|m| m.contains("nonexistent")));
    }

    #[test]
    fn lint_step_target_loads_step_file() {
        let temp = setup_project(
            r#"
app_name: Test
steps:
  other:
    command: "echo other"
"#,
        );
        let steps_dir = temp.path().join(".bivvy").join("steps");
        fs::create_dir_all(&steps_dir).unwrap();
        fs::write(
            steps_dir.join("deps.yml"),
            "command: yarn install\ntitle: Install deps\n",
        )
        .unwrap();

        let args = LintArgs {
            target: Some("deps".to_string()),
            ..Default::default()
        };
        let cmd = LintCommand::new(temp.path(), args);
        let mut ui = MockUI::new();
        let result = cmd.execute(&mut ui).unwrap();
        assert!(result.success);
    }

    #[test]
    fn lint_all_flag_uses_full_merge() {
        let temp = setup_project(
            r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#,
        );
        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        fs::write(
            workflows_dir.join("ci.yml"),
            "description: CI\nsteps: [hello]\n",
        )
        .unwrap();

        let args = LintArgs {
            all: true,
            ..Default::default()
        };
        let cmd = LintCommand::new(temp.path(), args);
        let mut ui = MockUI::new();
        let result = cmd.execute(&mut ui).unwrap();
        assert!(result.success);
    }
}

//! Comprehensive system tests for `bivvy config`.
//!
//! Tests display of resolved configuration in YAML and JSON formats,
//! merged config with local overrides, variables, and error conditions.
//!
//! These tests verify documented behavior of the `config` command:
//!   * Default output is YAML (same as `--yaml`).
//!   * `--json` emits a parseable JSON object of the resolved config.
//!   * `--merged` applies `.bivvy/config.local.yml` on top of the project
//!     config and lists both source files in the header.
//!   * Missing configuration exits with code 2 and the documented
//!     `No configuration found. Run 'bivvy init' first.` error.
//!   * Malformed YAML exits non-zero with a parse error surfaced to the
//!     user.
//!
//! Output assertions prefer `insta` snapshots over `contains(...)` checks
//! so structural regressions in YAML/JSON are caught rather than glossed
//! over by fuzzy substring matches, and every test verifies the process
//! exit code.
#![cfg(unix)]

mod system;

use std::fs;
use system::helpers::*;

// ─────────────────────────────────────────────────────────────────────
// Configs
//
// Every fixture uses real tool invocations (git/cargo/rustc) rather
// than shell builtins. Even though `config` never executes the steps,
// the commands are preserved in the rendered config and show up in
// snapshots, so keeping them realistic prevents the file from drifting
// into a pile of `echo foo` placeholders over time.
// ─────────────────────────────────────────────────────────────────────

/// Non-trivial baseline config: two steps with a dependency relationship
/// and an explicit `defaults.output` setting. Exercised by most of the
/// happy-path snapshot tests.
const CONFIG: &str = r#"app_name: "ConfigTest"
settings:
  defaults:
    output: verbose
steps:
  deps:
    title: "Install dependencies"
    command: "cargo --version"
  build:
    title: "Build project"
    command: "rustc --version"
    depends_on: [deps]
workflows:
  default:
    steps: [deps, build]
"#;

/// Smallest usable config — single step, single workflow. Used to
/// verify the config command doesn't crash on minimal input and to
/// pin down the "small config" snapshot shape.
const MINIMAL_CONFIG: &str = r#"app_name: "Minimal"
steps:
  one:
    command: "git --version"
workflows:
  default:
    steps: [one]
"#;

/// Config using the `vars` feature — exercises variable interpolation
/// captured in the resolved output.
const CONFIG_WITH_VARS: &str = r#"app_name: "VarConfig"
vars:
  version:
    command: "git --version"
  env_name:
    value: "development"
steps:
  show:
    command: "git log --grep '${version}' --branches '${env_name}'"
workflows:
  default:
    steps: [show]
"#;

/// Config with step-level `env:` entries. Ensures the config command
/// faithfully round-trips env blocks (including keys that look like
/// secrets — `config` is documented to show them verbatim; masking is
/// a run-time concern).
const CONFIG_WITH_SECRETS: &str = r#"app_name: "SecretConfig"
steps:
  deploy:
    command: "git --version"
    env:
      API_KEY: "secret-key-123"
      DB_PASSWORD: "hunter2"
workflows:
  default:
    steps: [deploy]
"#;

    fn default() -> Self {
        Self {
            logging: true,
            log_retention_days: default_log_retention_days(),
            log_retention_mb: default_log_retention_mb(),
        }
    }
}

impl LoggingSettings {
    /// Convert to a [`RetentionPolicy`](crate::logging::RetentionPolicy).
    pub fn to_retention_policy(&self) -> crate::logging::RetentionPolicy {
        crate::logging::RetentionPolicy {
            max_age_days: self.log_retention_days,
            max_size_mb: self.log_retention_mb,
        }
    }
}

fn default_log_retention_days() -> u32 {
    30
}

fn is_default_log_retention_days(v: &u32) -> bool {
    *v == default_log_retention_days()
}

fn default_log_retention_mb() -> u64 {
    500
}

fn is_default_log_retention_mb(v: &u64) -> bool {
    *v == default_log_retention_mb()
}

/// Execution-related settings (parallelism, history, updates).
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct ExecutionSettings {
    /// Enable parallel execution
    #[serde(default, skip_serializing_if = "is_false")]
    pub parallel: bool,

    /// Maximum concurrent steps
    #[serde(
        default = "default_max_parallel",
        skip_serializing_if = "is_default_max_parallel"
    )]
    pub max_parallel: usize,

    /// History retention count
    #[serde(
        default = "default_history_retention",
        skip_serializing_if = "is_default_history_retention"
    )]
    pub history_retention: usize,

    /// Use the diagnostic funnel pipeline for step failure recovery.
    ///
    /// When true, step failures are analyzed by a multi-stage pipeline that
    /// produces ranked resolution candidates. When false, the legacy pattern
    /// registry is used (single fix per error). Default: true.
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub diagnostic_funnel: bool,

    /// Enable automatic background updates.
    ///
    /// When true, bivvy checks for new versions in the background after each
    /// run and automatically installs updates so the next invocation uses the
    /// latest version. Set to false to disable (users can still run `bivvy update`).
    #[serde(default = "default_auto_update")]
    pub auto_update: bool,

    /// Global default rerun window for all steps.
    /// Steps can override this with their own `rerun_window` field.
    /// Accepts duration strings: `"4h"`, `"30m"`, `"7d"`, `"0"`/`"never"`, `"forever"`.
    /// Default: `"4h"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default_rerun_window: Option<String>,
}

impl Default for ExecutionSettings {
    fn default() -> Self {
        Self {
            parallel: false,
            max_parallel: default_max_parallel(),
            history_retention: default_history_retention(),
            diagnostic_funnel: true,
            auto_update: default_auto_update(),
            default_rerun_window: None,
        }
    }
}

/// Environment variable settings (global env, env files, secret patterns).
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct EnvVarSettings {
    /// Global environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Global env file to load
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,

    /// Additional secret patterns to mask
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub secret_env: Vec<String>,
