42	    description: Option<String>,
43	    #[serde(skip_serializing_if = "Option::is_none")]
44	    title: Option<String>,
45	    #[serde(skip_serializing_if = "Vec::is_empty")]
46	    depends_on: Vec<String>,
47	    #[serde(skip_serializing_if = "std::ops::Not::not")]
48	    skipped: bool,
49	}
50	
51	/// A single workflow in JSON output.
52	#[derive(Debug, Serialize)]
53	struct WorkflowJsonEntry {
54	    name: String,
55	    steps: Vec<String>,
56	    #[serde(skip_serializing_if = "Option::is_none")]
57	    description: Option<String>,
58	}
