60	/// The list command implementation.
61	pub struct ListCommand {
62	    project_root: PathBuf,
63	    args: ListArgs,
64	    config_override: Option<PathBuf>,
65	}
66	
67	impl ListCommand {
68	    /// Create a new list command.
69	    pub fn new(project_root: &Path, args: ListArgs) -> Self {
70	        Self {
71	            project_root: project_root.to_path_buf(),
72	            args,
73	            config_override: None,
74	        }
75	    }
76	
77	    /// Set an override config path.
78	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
79	        self.config_override = config_override;
80	        self
81	    }
82	
83	    /// Get the project root path.
84	    pub fn project_root(&self) -> &Path {
85	        &self.project_root
86	    }
87	
88	    /// Get the command arguments.
89	    pub fn args(&self) -> &ListArgs {
90	        &self.args
91	    }
92	
93	    /// Resolve the target environment using the priority chain.
94	    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
95	        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
96	    }
97	
98	    /// Build the configuration view to display.
99	    ///
100	    /// The selection rules:
101	    /// * `--all` or `--config` override → full merged load (legacy).
102	    /// * Positional `<name>` → that workflow file plus project context.
103	    /// * Otherwise → project config + discovery (names from filename
104	    ///   stems, headers parsed for workflow descriptions).
105	    fn build_view(&self) -> Result<BivvyConfig> {
106	        if self.config_override.is_some() {
107	            return load_config(&self.project_root, self.config_override.as_deref());
108	        }
109	        if self.args.all {
110	            return load_merged_config(&self.project_root);
111	        }
112	
113	        let discovery = Discovery::new(&self.project_root);
114	        let mut cfg = match load_project_config(&self.project_root) {
115	            Ok(c) => c,
116	            Err(BivvyError::ConfigNotFound { .. }) => BivvyConfig::default(),
117	            Err(e) => return Err(e),
118	        };
119	
120	        if let Some(ref name) = self.args.target {
121	            // Detail view for a single workflow file. Project config gives
122	            // step definitions; the workflow file overrides/adds.
123	            let path =
124	                discovery
125	                    .workflow_path(name)
126	                    .ok_or_else(|| BivvyError::ConfigValidationError {
